-- 🌾 Script 132 — A-FEAT-1420: STOCK DECLARADO AL 30/06/2025 (MSA) + PASTURAS — DATOS
-- JMS 29/10: «respecto de stock podés ir para adelante con todo». Generado por Claude desde su planilla:
--   «- STOCKS - GRANOS - INSUMOS AGRIC + GANADEROS - SEMENTERAS - GAS OIL.xlsx» (hojas 2 y 5) y «BAPU JMS USS 2025.xlsx» (hoja «stock», pasturas).
-- · 1 categoría nueva (Forraje) y los productos que no existían, con cantidad 0 (el stock de la app NO cambia).
-- · Una fila por renglón de la planilla en productivo.stock_inicio (versión jms, fecha 30/06/2025) con su fuente.
-- · Las 3 pasturas en productivo.pasturas.
-- Deshacer: 132-stock-inicio-msa-30-06-2025-deshacer.sql (borra por los ids de acá; frena si un producto ya tiene movimientos).
-- ════════════════════════════════════════════════════════════════════════════════════════════════
begin;
do $$ begin if exists (select 1 from productivo.stock_inicio where fuente like '%STOCKS - GRANOS%') then raise exception 'el 132 ya corrió'; end if; end $$;
commit;
notify pgrst, 'reload schema';

-- Control: filas, emparejados y total en pesos (tiene que dar 5.256.210 de agroquímicos/vet. + 23.220.734,08 de forrajes + 3.253.500 de gas oil)
select rubro, emparejado, count(*), sum(valor_pesos) from productivo.stock_inicio where fecha = '2025-06-30' group by 1,2 order by 1,2;
